const fs=require('node:fs'),path=require('node:path');
const root=path.resolve(__dirname,'..'),source=path.join(root,'web'),target=path.join(root,'www');
// This folder is generated by this script and is always inside the project.
if(path.dirname(target)!==root)throw new Error('Invalid output directory');
fs.mkdirSync(target,{recursive:true});fs.cpSync(source,target,{recursive:true});
const preview=process.env.JOLLYBOX_PREVIEW==='true';let html=fs.readFileSync(path.join(source,'index.html'),'utf8');
if(preview)html=html.replace('<body>','<body data-explore="true">');
fs.writeFileSync(path.join(target,'index.html'),html);
fs.writeFileSync(path.join(target,'build-info.json'),JSON.stringify({edition:'Naughty Elf Village',year:2026,preview},null,2));
console.log('Built JollyBox: '+(preview?'all-unlocked review':'date-locked calendar'));
